// Remote send reservations and completed receipts: durable before admission, uncertain after an interrupted effect, never automatically evicted; only payload hashes are stored.
const crypto = require('node:crypto');
const { RemoteError } = require('./serviceErrors.cjs');
const { writeDurable } = require('./durableWrite.cjs');
const { encryptForStore } = require('../platform/encryptedStore.cjs');

const VERSION = 1;
/** An uncertain send needs informed inspection, never a new id generated by an automatic retry. */
const UNSURE = 'This message may have reached the chat. Check the chat before explicitly choosing whether to send another message.';

const hashOf = (/** @type {string} */ text) => crypto.createHash('sha256').update(text).digest('hex');

/**
 * @typedef {{ print: string, state: 'pending' | 'done', result?: any, at: number }} Entry
 */
class SendLedger {
  /**
   * @param {object} o
   * @param {string | null} [o.file] where the record is kept; none keeps it in memory only
   * @param {import('./sealedJson.cjs').FsPromises} [o.fs]
   * @param {import('./sealedJson.cjs').SafeStorage | null} [o.safe] seals the file like the other Mobile Remote files; without it the file is plain JSON (a record from before sealing is still read, and written sealed at the next save)
   * @param {() => number} [o.now]
   * @param {number} [o.max] how many entries are kept
   * @param {(what: string, error: unknown) => void} [o.note] where a failure to save goes
   */
  constructor(o = {}) {
    this.file = o.file ?? null;
    this.fs = o.fs;
    this.safe = o.safe ?? null;
    this.now = o.now ?? Date.now;
    this.max = o.max ?? 1000;
    this.note = o.note ?? (() => undefined);
    /** @type {Map<string, Entry>} */
    this.entries = new Map();
    /** @type {Map<string, Promise<any>>} the sends running in this process */
    this.running = new Map();
    this.saving = Promise.resolve();
    /** @type {Promise<void> | null} the record is read when the first message needs it, not when Mobile Remote starts */
    this.loading = null;
    this.loadFailed = false;
    this.healthy = !this.file;
    /** @type {Promise<boolean> | null} concurrent hello probes share one durable write */
    this.probing = null;
  }

  load() {
    this.loading ??= this.file ? this.#load() : Promise.resolve();
    return this.loading;
  }

  async #load() {
    let text;
    try {
      text = await /** @type {any} */ (this.fs).readFile(this.file, 'utf8');
    } catch (error) {
      if (/** @type {any} */ (error)?.code !== 'ENOENT') {
        this.loadFailed = true;
        this.note('read the sent-message record', error);
      }
      return;
    }
    try {
      const data = JSON.parse(
        this.safe && !text.trimStart().startsWith('{') ? this.safe.decryptString(Buffer.from(text.trim(), 'base64')) : text,
      );
      if (data?.v !== VERSION || !Array.isArray(data.entries)) throw new Error('not a sent-message record');
      const loaded = new Map();
      for (const row of data.entries) {
        if (!Array.isArray(row) || row.length !== 2) throw new Error('not a sent-message entry');
        const [key, e] = row;
        if (
          typeof key !== 'string' ||
          typeof e?.print !== 'string' ||
          !['pending', 'done'].includes(e.state) ||
          !Number.isFinite(e.at) ||
          loaded.has(key)
        )
          throw new Error('not a sent-message entry');
        loaded.set(key, { print: e.print, state: e.state, result: e.result, at: e.at });
      }
      this.entries = loaded;
    } catch (error) {
      // Unreadable history cannot prove that an id was never dispatched. Preserve it and refuse new effects.
      this.loadFailed = true;
      this.note('read the sent-message record', error);
    }
  }

  /** A disk-backed ledger advertises readiness only after a successful durable probe; a probe can recover a write failure. */
  async ready() {
    await this.load();
    if (!this.file || this.loadFailed) return false;
    if (this.healthy) return true;
    this.probing ??= this.#save()
      .then(
        () => this.healthy,
        () => false,
      )
      .finally(() => {
        this.probing = null;
      });
    return this.probing;
  }

  /** Writes what is known now; saves run one after another so the file is always one whole state. */
  #save(/** @type {string | undefined} */ omit = undefined) {
    if (!this.file) return Promise.resolve();
    const done = this.saving.then(async () => {
      const text = JSON.stringify({ v: VERSION, entries: [...this.entries].filter(([key]) => key !== omit) });
      if (!this.safe) return writeDurable(/** @type {any} */ (this.fs), /** @type {string} */ (this.file), text);
      // sealed like the device list; without encryption nothing is written (the record then lives in memory only)
      const sealed = encryptForStore(this.safe, text);
      if (!sealed.ok) throw new Error('Remote access needs encryption, which this Mac can’t offer now');
      await writeDurable(/** @type {any} */ (this.fs), /** @type {string} */ (this.file), `${sealed.value}\n`);
    });
    this.saving = done.then(
      () => {
        this.healthy = true;
      },
      (error) => {
        this.healthy = false;
        this.note('save the sent-message record', error);
      },
    );
    return done;
  }

  /**
   * The callback is an effect: an arbitrary throw is uncertain. Only a locally branded pre-admission rejection releases it.
   * Existing v1 entries (including legacy colon keys) remain valid and never expire, including pending records.
   * @param {string} key structured owner/method/chat/send identity
   * @param {string} what canonical payload, hashed on disk
   * @param {() => Promise<any>} make
   * @param {{ key: string, what: string } | undefined} [legacy] an ordinary send's existing v1 identity/fingerprint
   */
  async run(key, what, make, legacy) {
    await this.load();
    if (this.loadFailed) throw unavailable();
    const oldKey = legacy && this.entries.has(legacy.key) ? legacy.key : key;
    const print = hashOf(oldKey !== key && legacy ? legacy.what : what);
    const earlier = this.entries.get(oldKey);
    if (earlier) {
      if (earlier.print !== print) throw new RemoteError('send_conflict', 'That send id was used for a different message.');
      const live = this.running.get(oldKey);
      if (live) return live;
      if (earlier.state === 'done') return earlier.result;
      throw new RemoteError('send_uncertain', UNSURE);
    }
    if (this.entries.size >= this.max)
      throw new RemoteError(
        'send_capacity',
        'The sent-message record is full. This attempt was not sent. Contact support before retrying.',
      );
    this.entries.set(key, { print, state: 'pending', at: this.now() });
    const result = (async () => {
      try {
        // Never dispatch on a best-effort reservation. A partial write can leave a pending record but no effect.
        await this.#save();
      } catch {
        this.entries.delete(key);
        throw unavailable();
      }
      let value;
      try {
        value = await make();
      } catch (error) {
        if (error instanceof NotSent) {
          try {
            await this.#save(key);
          } catch {
            throw unavailable();
          }
          this.entries.delete(key);
          throw error.cause;
        }
        // Controller admission and the external effect are not one transaction. Never turn an unknown throw into permission to replay.
        throw new RemoteError('send_uncertain', UNSURE);
      }
      this.entries.set(key, { print, state: 'done', result: value, at: this.now() });
      try {
        await this.#save();
      } catch {
        this.entries.set(key, { print, state: 'pending', at: this.now() });
        throw new RemoteError('send_uncertain', UNSURE);
      }
      return value;
    })().finally(() => this.running.delete(key));
    this.running.set(key, result);
    return result;
  }
}

/** The ledgers of this process by file: Mobile Remote stopping and starting again must not give a send still running a second ledger over the same file. */
const SHARED = new Map();

/** @param {string} file @param {ConstructorParameters<typeof SendLedger>[0]} o */
function sharedLedger(file, o) {
  if (!SHARED.has(file)) SHARED.set(file, new SendLedger({ ...o, file }));
  return SHARED.get(file);
}

/** What the end of the process does to them: the next ledger reads the file, and a send that was running is then an unfinished one. */
function dropSharedLedgers() {
  SHARED.clear();
}

/** Only this module can brand a refusal proven to occur before the admission callback. */
class NotSent extends Error {
  constructor(/** @type {unknown} */ cause) {
    super('Not admitted', { cause });
  }
}
const unavailable = () =>
  new RemoteError(
    'send_unavailable',
    'The sent-message record is unavailable. This attempt was not sent. Retry when storage is available.',
  );

/** Wrap preparation; the production sender calls admit synchronously immediately before handing input to the controller. */
async function beforeSend(/** @type {(admit: () => void) => Promise<any>} */ prepare) {
  let admitted = false;
  try {
    return await prepare(() => {
      admitted = true;
    });
  } catch (error) {
    if (!admitted) throw new NotSent(error);
    throw error;
  }
}

module.exports = { SendLedger, UNSURE, sharedLedger, dropSharedLedgers, beforeSend };
